public class Main {
    // Returns the letter grade for a score from 0 to 100,
    // or "invalid" for a score outside that range.
    static String letterGrade(int score) {
        if (score < 0 || score > 100) {
            return "invalid";
        }
        if (score >= 90) {
            return "A";
        }
        if (score >= 80) {
            return "B";
        }
        return "C or below";
    }

    public static void main(String[] args) {
        System.out.println("75 expects C or below: " + letterGrade(75));
        System.out.println("90 expects A: " + letterGrade(90));
        System.out.println("-5 expects invalid: " + letterGrade(-5));
    }
}

